#!/usr/bin/env python3
# THE NUMBERS WALK sitting 15 — THE REFUGE CITIES (2026-09-13): THE CLAIMS of Numbers 35:1-34, one manifest for the one draft unit, read off
# this sitting's ledger, every claim LABELED (World/step9/CLAIM_LABELS.md's vocabulary), a machine check where the ink allows — every
# he_contains substring CUT FROM THE SNAPSHOT STORE'S OWN BYTES by the word's CONSONANTS: the check is the word's LONGEST PIECE WHOLE (never
# a prefix fragment; the floor four code points). Claim IDs MS35A- (Masei, chapter 35). Written once (the file must not exist; the ID prefix
# checked absent from every existing manifest and unit). Every source cite is checked against the ledger's CITE INDEX before a byte is written.
import json, os, re, sqlite3, glob
ROOT = '<repo-old>'
DATE = '2026-09-13'
UID = 'num_35_refuge_cities'; PRE = 'MS35A'
db = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
def cut(book, ch, v, word, nth=0):
    rows = db.execute("SELECT w.idx, w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, v)).fetchall()
    plain = lambda h: ''.join(c for c in h if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
    hit = [(i, h) for i, h in rows if plain(h) == word]
    assert len(hit) > nth, (book, ch, v, word, hit)
    idx, he = hit[nth]
    piece = max(he.split('/'), key=len)
    assert len(piece) >= 4, (book, ch, v, word, he.split('/'))
    return idx, piece
def hc(ref, word, note, nth=0):
    b, cv = ref.split(' '); c, v = map(int, cv.split(':'))
    idx, sub = cut(b, c, v, word, nth)
    return {"type": "he_contains", "ref": ref, "idx": idx, "contains": sub, "note": note}
def onk(lo, hi): return '; '.join(f'Onkelos Num 35:{v}' for v in range(lo, hi + 1))
def sif(*rows): return '; '.join(f'Sifrei Bamidbar {r}' for r in rows)
